program.# The query buttons on their panel. Each:
# לחצני השאילתה בסרגל שלהם. כל אחד מהם שולח את צילום המסך ל-Google:
#   name: הרמז של הלחצן;
#   mode: לאן צילום המסך נשלח:
#     "ai": ה-AI של Google עונה על ההנחיה הקצרה במילים, מעל התוצאות של
#       התמונה והשאלה;
#     "chat": מצב AI עצמו (google.com/ai) בחלון של התוכנה: התוכנה מכניסה לשם את
#       צילום המסך ואת השאלה ושולחת אותם; החלון מופיע ליד האזור שנבחר, ובו רק
#       השיחה והשדה לשאלה הבאה; בהחזקה, הלחצן שואל בקול שאלה משלכם במקום
#       ההנחיה הקצרה, כל עוד מחזיקים אותו;
#     "answer": אותו דבר, אבל החלון מוסתר: התשובה מופיעה בכרטיס ליד האזור
#       שנבחר;
#     "images": חיפוש לפי תמונה בלי שאלה, בחלון של התוכנה ליד האזור שנבחר:
#       מיד ההתאמות המדויקות, הדפים שיש בהם את התמונה הזאת בדיוק, ולרוב
#       הכותרות שלהם אומרות מי או מה מופיע בה;
#   prompt: ההנחיה הקצרה, השאלה ל-AI, עבור "ai", "chat" ו-"answer";
#   key: המקש של הלחצן כשהמסך מוקפא;
#   icon: "google", "translate", "images" או "question".
# הלחצנים של ה-AI עומדים ראשונים בסרגל, והחיפוש לפי תמונה אחריהם.
# נכנסים לחשבון Google בחלון של התוכנה דרך חלון ההגדרות, "חשבון Google";
# כל עוד אף אחד לא נכנס, התוכנה מציעה להיכנס כשהיא מופעלת.
